parts.openscad_module:
$fn = 96;

inner_length     = 80;
inner_width      = 60;
inner_height     = 30;
wall_thickness   = 3;
bottom_wall      = 3;
lid_thickness    = 2;
lid_clearance    = 0.25;
lid_overlap      = 3;
standoff_h       = 4;
standoff_od      = 6;
pilot_hole_d     = 2.8;
boss_margin      = 6;

outer_length = inner_length + 2 * wall_thickness;
outer_width  = inner_width  + 2 * wall_thickness;
outer_height = inner_height + bottom_wall;

module enclosure_body() {
  difference() {
    cube([outer_length, outer_width, outer_height], center = true);
    translate([0, 0, bottom_wall/2])
      cube([inner_length, inner_width, outer_height], center = true);
    for (x = [-inner_length/2 + boss_margin, inner_length/2 - boss_margin])
      for (y = [-inner_width/2 + boss_margin, inner_width/2 - boss_margin])
        translate([x, y, -outer_height/2 + bottom_wall + standoff_h/2])
          cylinder(h = standoff_h + 2, d = pilot_hole_d, center = true, $fn = 32);
  }
  for (x = [-inner_length/2 + boss_margin, inner_length/2 - boss_margin])
    for (y = [-inner_width/2 + boss_margin, inner_width/2 - boss_margin])
      translate([x, y, -outer_height/2 + bottom_wall + standoff_h/2])
        cylinder(h = standoff_h, d = standoff_od, center = true, $fn = 32);
}

module enclosure_lid() {
  union() {
    cube([outer_length, outer_width, lid_thickness], center = true);
    translate([0, 0, -lid_overlap/2])
      cube([outer_length - 2*lid_clearance, outer_width - 2*lid_clearance, lid_overlap], center = true);
  }
}

enclosure_body();
